56	// applyStrategyOptions sets strategy_options on settings from CLI flags.
57	func (opts *EnableOptions) applyStrategyOptions(settings *EntireSettings) {
58		if opts.SkipPushSessions {
59			if settings.StrategyOptions == nil {
60				settings.StrategyOptions = make(map[string]interface{})
61			}
62			settings.StrategyOptions["push_sessions"] = false
63		}
64		if opts.CheckpointRemote != "" {
65			provider, repo, err := parseCheckpointRemoteFlag(opts.CheckpointRemote)
66			if err != nil {
67				fmt.Fprintf(os.Stderr, "Warning: invalid --checkpoint-remote format: %v\n", err)
68			} else {
69				if settings.StrategyOptions == nil {
70					settings.StrategyOptions = make(map[string]interface{})
71				}
72				settings.StrategyOptions["checkpoint_remote"] = map[string]any{
73					"provider": provider,
74					"repo":     repo,
75				}
76			}
77		}
78	}
