198	// settingsTargetFile determines which settings file to write to based on flags
199	// and which files exist. Unlike determineSettingsTarget, this correctly handles
200	// local-only repos by checking for settings.local.json when settings.json is absent.
201	func settingsTargetFile(ctx context.Context, useLocal, useProject bool) (string, string) {
202		if useLocal {
203			return settings.EntireSettingsLocalFile, configDisplayLocal
204		}
205		if useProject {
206			return settings.EntireSettingsFile, configDisplayProject
207		}
208	
209		// No explicit flag — write to whichever file exists.
210		// Check project file first, then local.
211		projectAbs, err := paths.AbsPath(ctx, settings.EntireSettingsFile)
212		if err == nil {
213			if _, statErr := os.Stat(projectAbs); statErr == nil {
214				return settings.EntireSettingsFile, configDisplayProject
215			}
216		}
217		localAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
218		if err == nil {
219			if _, statErr := os.Stat(localAbs); statErr == nil {
220				return settings.EntireSettingsLocalFile, configDisplayLocal
221			}
222		}
223	
224		// Neither exists — default to project
225		return settings.EntireSettingsFile, configDisplayProject
226	}
