239	// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
240	// Supported providers: "github".
241	func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
242		parts := strings.SplitN(value, ":", 2)
243		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
244			return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
245		}
246	
247		provider = parts[0]
248		repo = parts[1]
249	
250		switch provider {
251		case checkpointProviderGitHub:
252			// valid
253		default:
254			return "", "", fmt.Errorf("unsupported provider %q (supported: %s)", provider, checkpointProviderGitHub)
255		}
256	
257		repoParts := strings.SplitN(repo, "/", 2)
258		if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
259			return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
260		}
261	
262		return provider, repo, nil
263	}
