281	// runManageAgents shows which agents are currently enabled and lets the user
282	// add or remove agents. Deselecting an installed agent removes its hooks.
283	func runManageAgents(ctx context.Context, w io.Writer, opts EnableOptions, selectFn func(available []string) ([]string, error)) error {
284		installedNames := GetAgentsWithHooksInstalled(ctx)
285	
286		// Show currently installed agents
287		if len(installedNames) > 0 {
288			displayNames := make([]string, 0, len(installedNames))
289			for _, name := range installedNames {
290				if ag, err := agent.Get(name); err == nil {
291					displayNames = append(displayNames, string(ag.Type()))
292				}
293			}
294			fmt.Fprintf(w, "Enabled agents: %s\n\n", strings.Join(displayNames, ", "))
295		}
296	
297		// Build pre-selection set from installed agents
298		installedSet := make(map[types.AgentName]struct{}, len(installedNames))
299		for _, name := range installedNames {
300			installedSet[name] = struct{}{}
301		}
302	
303		// Check if we can prompt interactively
304		if !interactive.CanPromptInteractively() {
305			fmt.Fprintln(w, "Cannot show agent selection in non-interactive mode.")
306			fmt.Fprintln(w, "Use: entire configure --agent <name>")
307			return nil
308		}
309	
310		// Discover external agent plugins after the interactivity check to avoid
311		// scanning PATH (with a 10s timeout) in non-interactive contexts.
312		// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
313		// during setup the setting doesn't exist yet.
314		external.DiscoverAndRegisterAlways(ctx)
315	
316		// Build options from registered agents
317		agentNames := agent.List()
318		options := make([]huh.Option[string], 0, len(agentNames))
319		for _, name := range agentNames {
320			ag, err := agent.Get(name)
321			if err != nil {
322				continue
323			}
324			if _, ok := agent.AsHookSupport(ag); !ok {
325				continue
326			}
327			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
328				continue
329			}
330			opt := huh.NewOption(string(ag.Type()), string(name))
331			if _, installed := installedSet[name]; installed {
332				opt = opt.Selected(true)
333			}
334			options = append(options, opt)
335		}
336	
337		if len(options) == 0 {
338			return errors.New("no agents with hook support available")
339		}
340	
341		// Collect available agent names for the selector
342		availableNames := make([]string, 0, len(options))
343		for _, opt := range options {
344			availableNames = append(availableNames, opt.Value)
345		}
346	
347		var selectedAgentNames []string
348		if selectFn != nil {
349			var err error
350			selectedAgentNames, err = selectFn(availableNames)
351			if err != nil {
352				return fmt.Errorf("agent selection cancelled: %w", err)
353			}
354		} else {
355			form := NewAccessibleForm(
356				huh.NewGroup(
357					huh.NewMultiSelect[string]().
358						Title("Manage agents").
359						Description("Use space to select/deselect, enter to confirm.").
360						Options(options...).
361						Value(&selectedAgentNames),
362				),
363			)
364			if err := form.Run(); err != nil {
365				return fmt.Errorf("agent selection cancelled: %w", err)
366			}
367		}
368	
369		// Nothing selected and nothing installed — no-op.
370		if len(selectedAgentNames) == 0 && len(installedNames) == 0 {
371			targetFile, _ := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
372			changed, err := maybePromptVercelDeploymentDisable(ctx, w, targetFile, nil)
373			if err != nil {
374				return err
375			}
376			if !changed {
377				fmt.Fprintln(w, "No changes made.")
378			}
379			return nil
380		}
381	
382		err := applyAgentChanges(ctx, w, selectedAgentNames, installedNames, opts)
383		if err == nil && len(selectedAgentNames) == 0 {
384			fmt.Fprintln(w, "To add agents again, run: entire configure --agent <name>")
385		}
386		return err
387	}
