389	// applyAgentChanges computes added/removed agent sets from the selection and
390	// installs or uninstalls hooks accordingly.
391	func applyAgentChanges(ctx context.Context, w io.Writer, selectedAgentNames []string, installedNames []types.AgentName, opts EnableOptions) error {
392		installedSet := make(map[types.AgentName]struct{}, len(installedNames))
393		for _, name := range installedNames {
394			installedSet[name] = struct{}{}
395		}
396	
397		selectedSet := make(map[string]struct{}, len(selectedAgentNames))
398		for _, name := range selectedAgentNames {
399			selectedSet[name] = struct{}{}
400		}
401	
402		// Collect errors so partial successes are visible to the user.
403		var errs []error
404	
405		var addedAgents []agent.Agent
406		var reinstalledAgents []agent.Agent
407		for _, name := range selectedAgentNames {
408			ag, err := agent.Get(types.AgentName(name))
409			if err != nil {
410				errs = append(errs, fmt.Errorf("failed to get agent %s: %w", name, err))
411				continue
412			}
413			if _, wasInstalled := installedSet[types.AgentName(name)]; wasInstalled {
414				if opts.ForceHooks {
415					reinstalledAgents = append(reinstalledAgents, ag)
416				}
417				continue
418			}
419			addedAgents = append(addedAgents, ag)
420		}
421	
422		var removedAgents []agent.Agent
423		for _, name := range installedNames {
424			if _, stillSelected := selectedSet[string(name)]; stillSelected {
425				continue
426			}
427			ag, err := agent.Get(name)
428			if err != nil {
429				errs = append(errs, fmt.Errorf("failed to load deselected agent %s: %w", name, err))
430				continue
431			}
432			removedAgents = append(removedAgents, ag)
433		}
434	
435		if len(addedAgents) == 0 && len(reinstalledAgents) == 0 && len(removedAgents) == 0 && len(errs) == 0 {
436			targetFile, _ := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
437			changed, err := maybePromptVercelDeploymentDisable(ctx, w, targetFile, nil)
438			if err != nil {
439				return err
440			}
441			if !changed {
442				fmt.Fprintln(w, "No changes made.")
443			}
444			return nil
445		}
446		var successfullyAddedAgents []agent.Agent
447		for _, ag := range addedAgents {
448			if _, err := setupAgentHooks(ctx, w, ag, opts.LocalDev, opts.ForceHooks); err != nil {
449				errs = append(errs, fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err))
450			} else {
451				successfullyAddedAgents = append(successfullyAddedAgents, ag)
452			}
453		}
454	
455		var successfullyReinstalledAgents []agent.Agent
456		for _, ag := range reinstalledAgents {
457			if _, err := setupAgentHooks(ctx, w, ag, opts.LocalDev, opts.ForceHooks); err != nil {
458				errs = append(errs, fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err))
459			} else {
460				successfullyReinstalledAgents = append(successfullyReinstalledAgents, ag)
461			}
462		}
463	
464		var uninstalledAgents []agent.Agent
465		for _, ag := range removedAgents {
466			hookAgent, ok := agent.AsHookSupport(ag)
467			if !ok {
468				logging.Warn(ctx, "installed agent does not support hooks, skipping removal",
469					"agent", string(ag.Name()))
470				continue
471			}
472			if err := hookAgent.UninstallHooks(ctx); err != nil {
473				errs = append(errs, fmt.Errorf("failed to remove %s hooks: %w", ag.Type(), err))
474			} else {
475				uninstalledAgents = append(uninstalledAgents, ag)
476			}
477		}
478	
479		// Auto-enable external_agents setting if any new agent is external.
480		for _, ag := range append(successfullyAddedAgents, successfullyReinstalledAgents...) {
481			if external.IsExternal(ag) {
482				s, loadErr := LoadEntireSettings(ctx)
483				if loadErr != nil {
484					s = &EntireSettings{}
485				}
486				if !s.ExternalAgents {
487					s.ExternalAgents = true
488					var saveErr error
489					if opts.UseLocalSettings {
490						saveErr = SaveEntireSettingsLocal(ctx, s)
491					} else {
492						saveErr = SaveEntireSettings(ctx, s)
493					}
494					if saveErr != nil {
495						errs = append(errs, fmt.Errorf("failed to save external_agents setting: %w", saveErr))
496					}
497				}
498				break
499			}
500		}
501	
502		// Print summary of what succeeded
503		if len(successfullyAddedAgents) > 0 {
504			names := make([]string, 0, len(successfullyAddedAgents))
505			for _, ag := range successfullyAddedAgents {
506				names = append(names, string(ag.Type()))
507			}
508			fmt.Fprintf(w, "✓ Added agents: %s\n", strings.Join(names, ", "))
509		}
510		if len(successfullyReinstalledAgents) > 0 {
511			names := make([]string, 0, len(successfullyReinstalledAgents))
512			for _, ag := range successfullyReinstalledAgents {
513				names = append(names, string(ag.Type()))
514			}
515			fmt.Fprintf(w, "✓ Reinstalled agents: %s\n", strings.Join(names, ", "))
516		}
517		if len(uninstalledAgents) > 0 {
518			if len(successfullyAddedAgents) == 0 && len(successfullyReinstalledAgents) == 0 && len(addedAgents) == 0 && len(removedAgents) == len(installedNames) {
519				fmt.Fprintln(w, "All agents have been removed.")
520			} else {
521				names := make([]string, 0, len(uninstalledAgents))
522				for _, ag := range uninstalledAgents {
523					names = append(names, string(ag.Type()))
524				}
525				fmt.Fprintf(w, "✓ Removed agents: %s\n", strings.Join(names, ", "))
526			}
527		}
528	
529		vercelSettingsTarget, _ := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
530		if _, err := maybePromptVercelDeploymentDisable(ctx, w, vercelSettingsTarget, nil); err != nil {
531			errs = append(errs, err)
532		}
533	
534		return errors.Join(errs...)
535	}
