537	func newSetupCmd() *cobra.Command {
538		var opts EnableOptions
539		var agentName string
540		var removeAgentName string
541		var summarizeProvider string
542		var summarizeModel string
543	
544		cmd := &cobra.Command{
545			Use:   "configure",
546			Short: "Configure Entire in current repository",
547			Long: `Configure Entire with session tracking for your AI agent workflows.
548	
549	On first run, this configures Entire and installs agent hooks.
550	On subsequent runs, it lets you add or remove agents interactively.
551	
552	Use --remove to remove a specific agent non-interactively:
553	  entire configure --remove claude-code`,
554			RunE: func(cmd *cobra.Command, _ []string) error {
555				ctx := cmd.Context()
556				if _, err := paths.WorktreeRoot(ctx); err != nil {
557					fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run 'entire configure' from within a git repository.")
558					return NewSilentError(errors.New("not a git repository"))
559				}
560	
561				// Discover external agent plugins early so they're available
562				// for --agent, --remove, and interactive selection.
563				// Use DiscoverAndRegisterAlways so that --agent works on fresh repos
564				// where the external_agents setting hasn't been persisted yet.
565				external.DiscoverAndRegisterAlways(ctx)
566	
567				// Remove agent mode
568				if removeAgentName != "" {
569					return runRemoveAgent(ctx, cmd.OutOrStdout(), removeAgentName)
570				}
571	
572				// Non-interactive --agent mode
573				if cmd.Flags().Changed(agentFlagName) && agentName == "" {
574					printMissingAgentError(cmd.ErrOrStderr())
575					return NewSilentError(errors.New("missing agent name"))
576				}
577				if agentName != "" {
578					ag, err := agent.Get(types.AgentName(agentName))
579					if err != nil {
580						printWrongAgentError(cmd.ErrOrStderr(), agentName)
581						return NewSilentError(errors.New("wrong agent name"))
582					}
583					return setupAgentHooksNonInteractive(ctx, cmd.OutOrStdout(), ag, opts)
584				}
585	
586				// Settings-only mode: update strategy options / summary provider without agent selection
587				if settings.IsSetUpAny(ctx) && (hasStrategyFlags(cmd) || hasSummaryProviderFlags(cmd)) {
588					if hasStrategyFlags(cmd) {
589						if err := updateStrategyOptions(ctx, cmd.OutOrStdout(), opts); err != nil {
590							return err
591						}
592					}
593					if hasSummaryProviderFlags(cmd) {
594						if err := updateSummaryGenerationSettings(ctx, cmd.OutOrStdout(), summarizeProvider, summarizeModel, opts); err != nil {
595							return err
596						}
597					}
598					return nil
599				}
600	
601				// If already set up, show agents and let user add more
602				if settings.IsSetUpAny(ctx) {
603					return runManageAgents(ctx, cmd.OutOrStdout(), opts, nil)
604				}
605	
606				// Fresh repo — run full setup flow
607				return runSetupFlow(ctx, cmd.OutOrStdout(), opts)
608			},
609		}
