1021	// uninstallDeselectedAgentHooks removes hooks for agents that were previously
1022	// installed but are not in the selected list. This handles the case where a user
1023	// re-runs `entire enable` and deselects an agent.
1024	func uninstallDeselectedAgentHooks(ctx context.Context, w io.Writer, selectedAgents []agent.Agent) error {
1025		installedNames := GetAgentsWithHooksInstalled(ctx)
1026		if len(installedNames) == 0 {
1027			return nil
1028		}
1029	
1030		selectedSet := make(map[types.AgentName]struct{}, len(selectedAgents))
1031		for _, ag := range selectedAgents {
1032			selectedSet[ag.Name()] = struct{}{}
1033		}
1034	
1035		var errs []error
1036		for _, name := range installedNames {
1037			if _, selected := selectedSet[name]; selected {
1038				continue
1039			}
1040			ag, err := agent.Get(name)
1041			if err != nil {
1042				continue
1043			}
1044			hookAgent, ok := agent.AsHookSupport(ag)
1045			if !ok {
1046				continue
1047			}
1048			if err := hookAgent.UninstallHooks(ctx); err != nil {
1049				errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
1050			} else {
1051				fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
1052			}
1053		}
1054		return errors.Join(errs...)
1055	}
