1473	// shellCompletionComment is the comment preceding the completion line
1474	const shellCompletionComment = "# Entire CLI shell completion"
1475	
1476	// errUnsupportedShell is returned when the user's shell is not supported for completion.
1477	var errUnsupportedShell = errors.New("unsupported shell")
1478	
1479	// shellCompletionTarget returns the rc file path and completion lines for the
1480	// user's current shell.
1481	func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
1482		home, err := os.UserHomeDir()
1483		if err != nil {
1484			return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
1485		}
1486	
1487		shell := os.Getenv("SHELL")
1488		switch {
1489		case strings.Contains(shell, "zsh"):
1490			return "Zsh",
1491				filepath.Join(home, ".zshrc"),
1492				"autoload -Uz compinit && compinit && source <(entire completion zsh)",
1493				nil
1494		case strings.Contains(shell, "bash"):
1495			bashRC := filepath.Join(home, ".bashrc")
1496			if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
1497				bashRC = filepath.Join(home, ".bash_profile")
1498			}
1499			return "Bash",
1500				bashRC,
1501				"source <(entire completion bash)",
1502				nil
1503		case strings.Contains(shell, "fish"):
1504			return "Fish",
1505				filepath.Join(home, ".config", "fish", "config.fish"),
1506				"entire completion fish | source",
1507				nil
1508		default:
1509			return "", "", "", errUnsupportedShell
1510		}
1511	}
