1513	// promptShellCompletion offers to add shell completion to the user's rc file.
1514	// Only prompts if completion is not already configured.
1515	func promptShellCompletion(w io.Writer) error {
1516		shellName, rcFile, completionLine, err := shellCompletionTarget()
1517		if err != nil {
1518			if errors.Is(err, errUnsupportedShell) {
1519				fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
1520				return nil
1521			}
1522			return fmt.Errorf("shell completion: %w", err)
1523		}
1524	
1525		if isCompletionConfigured(rcFile) {
1526			fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
1527			return nil
1528		}
1529	
1530		var selected string
1531		form := NewAccessibleForm(
1532			huh.NewGroup(
1533				huh.NewSelect[string]().
1534					Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
1535					Options(
1536						huh.NewOption("Yes", "yes"),
1537						huh.NewOption("No", "no"),
1538					).
1539					Value(&selected),
1540			),
1541		)
1542	
1543		if err := form.Run(); err != nil {
1544			//nolint:nilerr // User cancelled - not a fatal error, just skip
1545			return nil
1546		}
1547	
1548		if selected != "yes" {
1549			return nil
1550		}
1551	
1552		if err := appendShellCompletion(rcFile, completionLine); err != nil {
1553			return fmt.Errorf("failed to update %s: %w", rcFile, err)
1554		}
1555	
1556		fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
1557		fmt.Fprintln(w, "  Restart your shell to activate")
1558	
1559		return nil
1560	}
