1881	// removeAgentHooks removes hooks from all agents that support hooks.
1882	func removeAgentHooks(ctx context.Context, w io.Writer) error {
1883		var errs []error
1884		for _, name := range agent.List() {
1885			ag, err := agent.Get(name)
1886			if err != nil {
1887				continue
1888			}
1889			hs, ok := agent.AsHookSupport(ag)
1890			if !ok {
1891				continue
1892			}
1893			wasInstalled := hs.AreHooksInstalled(ctx)
1894			if err := hs.UninstallHooks(ctx); err != nil {
1895				errs = append(errs, err)
1896			} else if wasInstalled {
1897				fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1898			}
1899		}
1900		return errors.Join(errs...)
1901	}
