1937	// removeAllShadowBranches removes all shadow branches.
1938	func removeAllShadowBranches(ctx context.Context) (int, error) {
1939		branches, err := strategy.ListShadowBranches(ctx)
1940		if err != nil {
1941			return 0, fmt.Errorf("failed to list shadow branches: %w", err)
1942		}
1943		if len(branches) == 0 {
1944			return 0, nil
1945		}
1946		deleted, _, err := strategy.DeleteShadowBranches(ctx, branches)
1947		return len(deleted), err
1948	}
